define(["content/scenario1","content/scenario2","content/scenario3","content/scenario4"],(function(scenario1,scenario2,scenario3,scenario4){var randomInteger=function(min,max){var rand=min-.5+Math.random()*(max-min+1);return rand=Math.round(rand)};return{lang:"en-us",title:"JNT601B Joint Functions Force Capabilities & Limitations",mission:"Joint Operations",playVideo:!0,failedAttempt:1,tutorialTiming:20,tutorial:[{text:"Click the resource tab at any time to review supporting materials for this activity.",x:500,y:590,arrow:"left",dwellTime:4e3,view:"scenario"},{text:"There are 10 subtasks listed here.",x:400,y:155,arrow:"left",dwellTime:4e3,view:"scenario"},{text:"This is the function library.",x:50,y:150,arrow:"left",dwellTime:4e3,view:"scenario"},{text:"Drag one function to the space on the left of each subtask.",x:200,y:100,arrow:"left",view:"scenario",dwellTime:4e3},{text:"This is the element library.",x:650,y:150,arrow:"right",view:"scenario",dwellTime:4e3},{text:"Drag one element to the space on the right of each subtask.",x:500,y:100,arrow:"right",view:"scenario",dwellTime:4e3},{text:"The RESET button will clear all selections.",x:465,y:580,arrow:"left",view:"scenario",dwellTime:4e3},{text:"When you are finished, click the SUBMIT button to receive feedback on your selections.",x:650,y:525,arrow:"right",view:"scenario",dwellTime:4e3}],passingScore:80,allowedStrikes:3,instruction:"You are assigned to the GCC planning staff for USGEOCOM. According to the most current Unified Command Plan (UCP), the USGEOCOM area of responsibility (AOR) is comprised of the 18-country region shown in the map.",gameInstruction:"You have two sets of tasks to accomplish. First, identify the joint function that best incorporates the subtask, and drag it into the function space; and second, identify the asset that can most effectively complete the subtask, and drag it into the element space. The joint functions can be used multiple times, but the forces in the element list can be used only once.",feedbacks:[{id:1,type:"correct",text:"You correctly applied the joint functions and asset capabilities and limitations to all assigned tasks. Great job!<br><br>"},{id:2,type:"correct",text:"Good work! You achieved a passing score; however, your solution showed some weakness as follows:<br><br><li>You have incorrectly assigned [functIC] function(s) to subtasks. </li><li>You currently have [eleIC] element(s) in less than ideal positions.</li><br><br>"},{id:3,type:"incorrect",text:"You have not successfully considered the joint functions and/or force capabilities and limitations for this scenario.<br><br>Consider this guidance as you try again. You need to review the functions and/or elements associated with the following subtasks:[subtasks] You may want to consider returning to the reading materials related to this topic to make sure you understand the joint functions and force capabilities and limitations."},{id:4,type:"incorrect",text:"You may want to consider returning to the reading materials related to this topic to make sure you understand the joint functions and force capabilities and limitations."}],endActivityText:"Nice job. You’ve shown that you understand the joint functions, as well as the capabilities and limitations of a range of joint forces. You were able to appropriately identify the joint functions and the appropriate joint force asset required for completion of each subtask while taking into account the available forces and mission requirements. These are key elements in the success of all joint operations. <br/><br/> Click END ACTIVITY to exit.",scenarios:[scenario1,scenario2,scenario3,scenario4],guidance:{voiceover:"assets/audio/JF_505_1.mp3"},getRandomScenarious:function(){var firstScenario,forceList;return[randomInteger(0,3),randomInteger(0,1)]}}}));